{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "A PET study in rats showed rapid brain uptake (peak ~1.2 SUV) for a piperazine-substituted biphenyl, demonstrating that direct piperazine attachment to an aromatic system is compatible with BBB passage.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "mCPP, a chloroarylpiperazine, reached brain concentrations about 50-fold higher than the parent drug in mice (brain/plasma AUC ratio), indicating strong CNS penetration for a small piperazine-containing molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "A pyrroloquinoxaline piperazine derivative had a brain/plasma ratio of 37.5 in rats and was classified as good penetration, supporting CNS access for piperazine-substituted heteroaromatic tricyclics.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "TFMPP, a trifluoromethylphenylpiperazine, showed a brain-to-blood Cmax ratio exceeding one order of magnitude in animals, confirming ready BBB crossing for arylpiperazines.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Perphenazine, a tricyclic phenothiazine with a piperazine-containing side chain, achieved high brain concentrations in mice, supporting CNS access for lipophilic tricyclic piperazines.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A piperazine-containing compound with reduced lipophilicity showed impaired CNS penetration (free plasma:CSF 5:1), but this is weakly transferable because the query is a lipophilic tricyclic thiazepine rather than a polar pyridazinone.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C06"],
      "claim": "Trimeprazine was not detected in lumbar CSF in three children, but this phenothiazine has known CNS activity and the non-detection may reflect assay/protein-binding factors; weak transfer to the query's direct piperazine-thiazepine core.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a lipophilic dibenzothiazepine with a directly attached piperazine, closely related to CNS-active arylpiperazine and tricyclic antipsychotic scaffolds. Multiple direct in vivo measurements in piperazine-containing analogues show good-to-high brain penetration, while the two negative records involve either a much more polar compound or a phenothiazine with a different side chain and are weakly transferable. Overall evidence supports meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule.",
    "All retrieved analogues have Morgan similarity below 0.35, limiting quantitative transfer.",
    "Contradictory CSF non-detection for trimeprazine is from a different scaffold and may reflect protein binding or assay sensitivity.",
    "No human data for the query or its closest analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

